import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.E8pQZ6KS.js";const u=JSON.parse('{"title":"汇编语言","description":"","frontmatter":{},"headers":[],"relativePath":"专业基础/汇编语言.md","filePath":"专业基础/汇编语言.md","lastUpdated":1792430298000}'),d={name:"专业基础/汇编语言.md"};function o(i,t,h,n,s,c){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="汇编语言" tabindex="-1">汇编语言 <a class="header-anchor" href="#汇编语言" aria-label="Permalink to &quot;汇编语言&quot;">​</a></h1><blockquote><p>离机器最近的语言。校内第 4 学期开设，是逆向工程与二进制安全的直通课——它给你「看穿程序本质」的眼睛。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>逆向（<a href="./../安全方向/二进制安全与逆向.html">二进制安全与逆向</a>）的第一步是读懂反汇编；</li><li>缓冲区溢出、ROP 等利用技术的核心是理解栈与指令流；</li><li>恶意代码分析（脱壳、混淆还原）离不开汇编层面的解读。</li></ul><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><ul><li>寄存器与寻址方式</li><li>常用指令（数据传送、算术、逻辑、控制转移、函数调用）</li><li>栈与函数调用约定（<code>call</code>/<code>ret</code>、栈帧）</li><li>与 C 语言对照：看编译器把代码变成什么</li></ul><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>《汇编语言》（王爽）</td><td>书</td><td>中文汇编入门经典，配套实验设计极好</td></tr><tr><td>《x86 汇编语言：从实模式到保护模式》</td><td>书</td><td>深入 x86 体系的进阶好书</td></tr><tr><td>CSAPP 第 3 章（程序的机器级表示）</td><td>书</td><td>以 C 视角学汇编，网安学生最推荐的路径</td></tr><tr><td><a href="https://godbolt.org/" target="_blank" rel="noreferrer">Compiler Explorer</a></td><td>在线工具</td><td>实时看 C 代码对应的汇编</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li>不要求「手写汇编」，要求「读懂汇编」——能对照 C 代码理解反汇编输出即可；</li><li>重点掌握<strong>栈帧布局与调用约定</strong>（x86-64 下参数如何传、返回值如何回）；</li><li>学完后立刻接 <a href="./../必学工具/逆向工具链.html">逆向工具链</a> 动手实践，趁热打铁。</li></ul>',10)])])}const b=a(d,[["render",o]]);export{u as __pageData,b as default};
